  s=replaceOnce(s,'export interface NumberingSettings {',`export interface DocumentEventRecord {\n  id: string;\n  documentId: string;\n  documentNumber: string;\n  type: DocumentEventType;\n  at: string;\n  note: string;\n  relatedDocumentId: string;\n  relatedDocumentNumber: string;\n  amount: string;\n  currency: string;\n}\n\nexport interface DocumentRevisionRecord {\n  id: string;\n  documentId: string;\n  documentNumber: string;\n  revision: number;\n  snapshot: LourexDocument;\n  createdAt: string;\n}\n\nexport interface NumberingSettings {`,'event and revision records');
