  s=replaceOnce(s,'  documents: LourexDocument[];\n  payments: PaymentRecord[];','  documents: LourexDocument[];\n  documentEvents: DocumentEventRecord[];\n  documentRevisions: DocumentRevisionRecord[];\n  payments: PaymentRecord[];','vault lifecycle arrays');
