  s=replaceOnce(s,'export function emptyItem(): DocumentItem {',`export function nextCreditNoteNumber(vault:VaultPayload):{number:string;vault:VaultPayload}{\n  const year=new Date().getFullYear();\n  const sourceNumbering=vault.appSettings.numbering;\n  const numbering={...sourceNumbering};\n  if(numbering.creditNoteYear!==year){numbering.creditNoteYear=year;numbering.creditNoteLast=0;}\n  const prefix=(numbering.creditNotePrefix||'CN').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8)||'CN';\n  numbering.creditNotePrefix=prefix;\n  const live=liveNumberReservations.get(sourceNumbering);\n  const reserved=live?.year===year?live.creditNote:0;\n  const used=new Set(vault.documents.map(document=>document.number.trim().toLowerCase()).filter(Boolean));\n  let seq=Math.max(0,Math.trunc(numbering.creditNoteLast||0),reserved);\n  let number='';\n  do{seq+=1;number=\`${'${prefix}-${year}-${String(seq).padStart(4, \'0\')}'}\`;}while(used.has(number.toLowerCase()));\n  numbering.creditNoteLast=seq;\n  const reservation: NumberReservation=live?.year===year?{...live}:{year,proforma:0,invoice:0,creditNote:0};\n  reservation.creditNote=seq;\n  liveNumberReservations.set(sourceNumbering,reservation);\n  return{number,vault:{...vault,appSettings:{...vault.appSettings,numbering}}};\n}\n\nexport function emptyItem(): DocumentItem {`,'credit note numbering function');
  s=replaceOnce(s,"id: makeId('doc'), kind, status: 'draft', number, issueDate,","id: makeId('doc'), kind, role:'standard', status: 'draft', lifecycleStatus:'active', revision:1, creditForId:'', creditForNumber:'', voidedAt:'', voidReason:'', number, issueDate,",'blank lifecycle fields');
  s=replaceOnce(s,"return { ...structuredClone(source), id: makeId('doc'), number, issueDate, dueDate, status: 'draft', convertedFromId: '', createdAt: now, updatedAt: now, items: source.items.map(i => ({ ...structuredClone(i), id: makeId('item') })) };","return { ...structuredClone(source), id: makeId('doc'), number, issueDate, dueDate, role:'standard', status: 'draft', lifecycleStatus:'active', revision:1, creditForId:'', creditForNumber:'', voidedAt:'', voidReason:'', convertedFromId: '', createdAt: now, updatedAt: now, items: source.items.map(i => ({ ...structuredClone(i), id: makeId('item') })) };",'duplicate lifecycle reset');
